package com.reviewbetterbonia.app.ui.quiz;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.Nullable;import com.reviewbetterbonia.app.MainActivity;import com.reviewbetterbonia.app.ui.*;import java.util.*;
public class CasualSetupFragment extends BaseFragment{
 @Nullable public View onCreateView(LayoutInflater i,ViewGroup c,Bundle b){android.content.Context x=requireContext();MainActivity a=app();LinearLayout p=Ui.page(x);Ui.add(p,Ui.heading(x,"Casual review"),Ui.dp(x,42));Ui.add(p,Ui.muted(x,"No rating pressure. Build a quiz around exactly what you want to practice.",14),Ui.dp(x,42));Spinner subject=new Spinner(x);ArrayAdapter<String> sa=new ArrayAdapter<>(x,android.R.layout.simple_spinner_dropdown_item,a.quiz.subjects);subject.setAdapter(sa);Ui.add(p,Ui.label(x,"Subject"),Ui.dp(x,28));Ui.add(p,subject,Ui.dp(x,52));Spinner category=new Spinner(x);Ui.add(p,Ui.label(x,"Category"),Ui.dp(x,28));Ui.add(p,category,Ui.dp(x,52));subject.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int pos,long id){String s=a.quiz.subjects.get(pos);List<String> cats=new ArrayList<>();cats.add("All Categories");cats.addAll("All Subjects".equals(s)?a.quiz.allCategories():a.quiz.categoriesFor(s));category.setAdapter(new ArrayAdapter<>(x,android.R.layout.simple_spinner_dropdown_item,cats));}});Ui.add(p,Ui.label(x,"Questions"),Ui.dp(x,28));Spinner count=new Spinner(x);String[] counts={"10","20","30","40","50","100"};count.setAdapter(new ArrayAdapter<>(x,android.R.layout.simple_spinner_dropdown_item,counts));Ui.add(p,count,Ui.dp(x,52));CheckBox timed=new CheckBox(x);timed.setText("Timed mode");timed.setTextSize(15);p.addView(timed);EditText seconds=new EditText(x);seconds.setHint("Seconds per question (default 30)");seconds.setInputType(2);Ui.add(p,seconds,Ui.dp(x,52));Ui.addWeight(p,new Space(x));Button start=Ui.button(x,"Start casual quiz",true);Ui.add(p,start,Ui.dp(x,56));start.setOnClickListener(v->{String s=subject.getSelectedItem().toString(),cat=category.getSelectedItem()==null?"All Categories":category.getSelectedItem().toString();int n=Integer.parseInt(count.getSelectedItem().toString());List<com.reviewbetterbonia.app.model.Question> pool=a.quiz.pool(s,cat);if(pool.size()<n){Toast.makeText(x,"Only "+pool.size()+" questions match this selection.",Toast.LENGTH_SHORT).show();return;}int sec=30;try{if(!seconds.getText().toString().trim().isEmpty())sec=Math.max(5,Integer.parseInt(seconds.getText().toString().trim()));}catch(Exception ignored){}a.navigate(QuizFragment.newCasual(s,cat,n,timed.isChecked(),sec),true);});Button back=Ui.button(x,"Back",false);back.setOnClickListener(v->requireActivity().getSupportFragmentManager().popBackStack());Ui.add(p,back,Ui.dp(x,52));return p;}
}
